// SHCUI types
export type SHCUIType =
  | 'button' | 'checkbox' | 'hslider' | 'vslider'
  | 'hbargraph' | 'vbargraph' | 'pad'
  | 'trigCue' | 'nextCue' | 'prevCue' | 'initCue'
  | 'trigCounter' | 'setRef';

export const SHCUI_TYPES: SHCUIType[] = [
  'button', 'checkbox', 'hslider', 'vslider',
  'hbargraph', 'vbargraph', 'pad',
  'trigCue', 'nextCue', 'prevCue', 'initCue',
  'trigCounter', 'setRef'
];

export interface SHCUIElement {
  paramPath: string;
  tab: string;
  type: SHCUIType;
  x: number;   // 0-100
  y: number;   // 0-100
  w: number;   // 0-100
  h: number;   // 0-100
  r: number;   // 0-255
  g: number;   // 0-255
  b: number;   // 0-255
  a: number;   // 0-255
}

export interface MotionMapping {
  paramPath: string;
  sensor: 'acc' | 'gyr';
  axis: 0 | 1 | 2;
  curve: 0 | 1 | 2;
  amin: number;
  amid: number;
  amax: number;
}

export interface MotionLibParam {
  id: number;
  address: string;
  showName: string;
  min: number;
  max: number;
  init: number;
}

export interface DspParam {
  id: number;
  address: string;
  min: number;
  max: number;
  init: number;
  accMeta?: string;
  gyrMeta?: string;
  motionMeta?: string;
  showNameMeta?: string;
}

export interface ConverterCall {
  sensor: 'acc' | 'gyr';
  paramId: number;
  axis: 0 | 1 | 2;
  curve: 0 | 1 | 2;
  amin: number;
  amid: number;
  amax: number;
  callSignature: string;
}

export interface CueEntry {
  index: number;
  tip: string;
}

export interface PackOptions {
  outputName: string;
  outputDir: string;
  dspContent: string;
  attachments: string[];
  includeAudio: boolean;
  includeLibs: boolean;
}

export interface UnpackResult {
  mainDspPath: string;
  mainDspContent: string;
  attachments: string[];
  tempDir: string;
}

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

export interface ParseResult<T> {
  data: T;
  errors: ParseError[];
}

export interface ParseError {
  paramPath: string;
  message: string;
}
