import type { SHCUIElement, MotionMapping, CueEntry } from './types';
import { SHCUIParser } from './SHCUIParser';
import { MotionParser } from './MotionParser';

export class DSPMetadataEditor {
  private shcuiParser = new SHCUIParser();
  private motionParser = new MotionParser();

  private findLabelIndex(dspCode: string, paramPath: string): { start: number; end: number; label: string } | null {
    const escaped = paramPath.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`"(${escaped}[^"]*)"`, 'g');
    const match = regex.exec(dspCode);
    if (!match) return null;
    return { start: match.index + 1, end: match.index + match[0].length - 1, label: match[1] };
  }

  private upsertMeta(label: string, tagName: string, newValue: string): string {
    const tagRegex = new RegExp(`\\[${tagName}:[^\\]]*\\]`, 'g');
    if (tagRegex.test(label)) return label.replace(new RegExp(`\\[${tagName}:[^\\]]*\\]`), `[${tagName}: ${newValue}]`);
    return label.trimEnd() + ` [${tagName}: ${newValue}]`;
  }

  private removeMeta(label: string, tagName: string): string {
    return label.replace(new RegExp(`\\s*\\[${tagName}:[^\\]]*\\]`, 'g'), '').trimEnd();
  }

  private applyToLabel(dspCode: string, paramPath: string, transform: (label: string) => string): string {
    const found = this.findLabelIndex(dspCode, paramPath);
    if (!found) return dspCode;
    return dspCode.slice(0, found.start) + transform(found.label) + dspCode.slice(found.end);
  }

  upsertSHCUI(dspCode: string, paramPath: string, element: SHCUIElement): string {
    const value = this.shcuiParser.serialize(element).replace(/^\[SHCUI:\s*/, '').replace(/\]$/, '');
    return this.applyToLabel(dspCode, paramPath, label => this.upsertMeta(label, 'SHCUI', value));
  }

  removeSHCUI(dspCode: string, paramPath: string): string {
    return this.applyToLabel(dspCode, paramPath, label => this.removeMeta(label, 'SHCUI'));
  }

  upsertMotion(dspCode: string, paramPath: string, mapping: MotionMapping): string {
    const value = this.motionParser.serialize(mapping).replace(/^\[(acc|gyr):\s*/, '').replace(/\]$/, '');
    return this.applyToLabel(dspCode, paramPath, label => this.upsertMeta(label, mapping.sensor, value));
  }

  removeMotion(dspCode: string, paramPath: string, sensor: 'acc' | 'gyr'): string {
    return this.applyToLabel(dspCode, paramPath, label => this.removeMeta(label, sensor));
  }

  upsertMotionLink(dspCode: string, paramPath: string, motionLibAddress: string): string {
    return this.applyToLabel(dspCode, paramPath, label => this.upsertMeta(label, 'motion', motionLibAddress));
  }

  removeMotionLink(dspCode: string, paramPath: string): string {
    return this.applyToLabel(dspCode, paramPath, label => this.removeMeta(label, 'motion'));
  }

  readMotionLink(dspCode: string, paramPath: string): string | null {
    const found = this.findLabelIndex(dspCode, paramPath);
    if (!found) return null;
    const match = found.label.match(/\[motion:\s*([^\]]+)\]/);
    return match ? match[1].trim() : null;
  }

  upsertShowName(dspCode: string, paramPath: string, showName: string): string {
    return this.applyToLabel(dspCode, paramPath, label => this.upsertMeta(label, 'showName', showName));
  }

  removeShowName(dspCode: string, paramPath: string): string {
    return this.applyToLabel(dspCode, paramPath, label => this.removeMeta(label, 'showName'));
  }

  upsertCueManager(dspCode: string, cueEntries: CueEntry[]): string {
    const content = cueEntries.map(e => `${e.index}:'${e.tip}'`).join('; ');
    const newMeta = `[touchCueManager: {${content}}]`;

    // Try to find the trigCue param label and add/update inline metadata there
    const trigCueLabelRegex = /"([^"]*\[SHCUI:[^\]]*trigCue[^\]]*\][^"]*)"/;
    const match = dspCode.match(trigCueLabelRegex);
    if (match) {
      const oldLabel = match[1];
      // Remove existing touchCueManager metadata if present
      const cleanLabel = oldLabel.replace(/\s*\[touchCueManager:[^\]]*\]/g, '').trimEnd();
      const newLabel = cleanLabel + ' ' + newMeta;
      return dspCode.replace(match[0], `"${newLabel}"`);
    }

    // Fallback: use declare statement (legacy / no trigCue param found)
    const declContent = cueEntries.map(e => `${e.index}:${e.tip}`).join('; ');
    const newDecl = `declare touchCueManager "{${declContent}}";`;
    const existingRegex = /declare\s+touchCueManager\s+"[^"]*"\s*;/;
    if (existingRegex.test(dspCode)) return dspCode.replace(existingRegex, newDecl);
    return newDecl + '\n' + dspCode;
  }
}
