import type { SHCUIElement, SHCUIType, CueEntry, ParseResult, ParseError } from './types';
import { parseParams } from './parseParams';
import { SHCUI_TYPES } from './types';

export class SHCUIParser {
  parse(dspCode: string): ParseResult<SHCUIElement[]> {
    const elements: SHCUIElement[] = [];
    const errors: ParseError[] = [];
    // Strip comments before parsing so metadata in comments is ignored
    const stripped = dspCode
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/\/\/[^\n]*/g, '');
    const regex = /"([^"]*\[SHCUI:[^\]]*\][^"]*)"/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(stripped)) !== null) {
      const fullLabel = match[1];
      const shcuiMatch = fullLabel.match(/\[SHCUI:\s*(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s*\]/);
      if (!shcuiMatch) continue;
      // Extract paramPath: everything before the first metadata [...] block
      // Handles labels like "[3]Resonance[acc:...]" and "h:[1]Hands/1[acc:...]"
      // Metadata blocks contain a colon. Ordering prefixes [1],[2] are NOT metadata.
      const metaIdx = fullLabel.search(/\[(?:SHCUI|acc|gyr|motion|showName|style|unit|hidden|tooltip|scale|integer|log|lin|knob|led|numerical|menu|radio|type|osc|midi|screencolor)[^\]]*\]/);
      const paramPath = (metaIdx !== -1 ? fullLabel.slice(0, metaIdx).trimEnd() : fullLabel).trim();
      const [, tab, typeStr, xStr, yStr, wStr, hStr, rStr, gStr, bStr, aStr] = shcuiMatch;
      const x = parseFloat(xStr), y = parseFloat(yStr), w = parseFloat(wStr), h = parseFloat(hStr);
      const r = parseInt(rStr), g = parseInt(gStr), b = parseInt(bStr), a = parseInt(aStr);
      let hasError = false;
      if (x < 0 || x > 100 || y < 0 || y > 100 || w < 0 || w > 100 || h < 0 || h > 100) {
        errors.push({ paramPath, message: `Coordinates/size out of range (0-100): x=${x} y=${y} w=${w} h=${h}` });
        hasError = true;
      }
      if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255 || a < 0 || a > 255) {
        errors.push({ paramPath, message: `Color values out of range (0-255): r=${r} g=${g} b=${b} a=${a}` });
        hasError = true;
      }
      if (!SHCUI_TYPES.includes(typeStr as SHCUIType)) {
        errors.push({ paramPath, message: `Unknown SHCUI type: "${typeStr}"` });
        hasError = true;
      }
      if (!hasError) elements.push({ paramPath, tab, type: typeStr as SHCUIType, x, y, w, h, r, g, b, a });
    }
    return { data: elements, errors };
  }

  serialize(element: SHCUIElement): string {
    const { tab, type, x, y, w, h, r, g, b, a } = element;
    // Round coordinates/size to integers to avoid floating-point noise
    return `[SHCUI: ${tab} ${type} ${Math.round(x)} ${Math.round(y)} ${Math.round(w)} ${Math.round(h)} ${Math.round(r)} ${Math.round(g)} ${Math.round(b)} ${Math.round(a)}]`;
  }

  parseCueManager(dspCode: string): CueEntry[] {
    const entries: CueEntry[] = [];
    // Strip comments before parsing
    const stripped = dspCode
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/\/\/[^\n]*/g, '');

    // Match inline label metadata: [touchCueManager: {1:'tip1'; 2:'tip2'; ...}]
    // or declare format: declare touchCueManager "{1:tip1; 2:tip2; ...}";
    const inlineMatch = stripped.match(/\[touchCueManager:\s*(\{[^}]*\})\]/);
    const declareMatch = stripped.match(/declare\s+touchCueManager\s+"(\{[^}]*\})"\s*;/);
    const rawContent = (inlineMatch?.[1] || declareMatch?.[1] || '')
      .replace(/^\{/, '').replace(/\}$/, '');

    if (!rawContent.trim()) return entries;

    for (const part of rawContent.split(';')) {
      const trimmed = part.trim();
      if (!trimmed) continue;
      const colonIdx = trimmed.indexOf(':');
      if (colonIdx === -1) continue;
      const index = parseInt(trimmed.slice(0, colonIdx).trim());
      // Strip surrounding quotes (single or double) from tip
      let tip = trimmed.slice(colonIdx + 1).trim();
      tip = tip.replace(/^['"]|['"]$/g, '');
      if (!isNaN(index) && tip) entries.push({ index, tip });
    }
    return entries;
  }
}
