import type { MotionMapping, ParseResult, ParseError } from './types';

export class MotionParser {
  parse(dspCode: string): ParseResult<MotionMapping[]> {
    const mappings: MotionMapping[] = [];
    const errors: ParseError[] = [];
    const regex = /"([^"]*\[(?:acc|gyr):[^\]]*\][^"]*)"/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(dspCode)) !== null) {
      const fullLabel = match[1];
      const paramPath = fullLabel.split('[')[0].trim();
      const metaRegex = /\[(acc|gyr):\s*(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s*\]/g;
      let metaMatch: RegExpExecArray | null;
      while ((metaMatch = metaRegex.exec(fullLabel)) !== null) {
        const [, sensor, axisStr, curveStr, aminStr, amidStr, amaxStr] = metaMatch;
        const axis = parseInt(axisStr) as 0 | 1 | 2;
        const curve = parseInt(curveStr) as 0 | 1 | 2;
        const amin = parseFloat(aminStr), amid = parseFloat(amidStr), amax = parseFloat(amaxStr);
        let hasError = false;
        if (![0, 1, 2].includes(axis)) { errors.push({ paramPath, message: `Invalid axis value: ${axis}` }); hasError = true; }
        if (![0, 1, 2].includes(curve)) { errors.push({ paramPath, message: `Invalid curve value: ${curve}` }); hasError = true; }
        if (amin >= amax) { errors.push({ paramPath, message: `amin (${amin}) must be less than amax (${amax})` }); hasError = true; }
        if (!hasError) mappings.push({ paramPath, sensor: sensor as 'acc' | 'gyr', axis, curve, amin, amid, amax });
      }
    }
    return { data: mappings, errors };
  }

  serialize(mapping: MotionMapping): string {
    const { sensor, axis, curve, amin, amid, amax } = mapping;
    return `[${sensor}: ${axis} ${curve} ${amin} ${amid} ${amax}]`;
  }
}
